// The hop variety catalogue: one hand-curated record per canonical variety, each figure copied from a
// published source named in the record. Nothing here is estimated. A field with no published source
// is left out, and build-hop-data.mjs turns every missing field into a stated gap with the sources
// that were checked.
//
// Chemistry strings are ranges as published: "11.0-13.0" is a range, "12.1" a single published value,
// "<1" means below 1 (no lower bound), "up to 71" means no lower bound. Units: alpha, beta and
// cohumulone in percent (cohumulone as a share of alpha acids), total oil in ml per 100 g, oil
// components in percent of total oil.

const HAAS = 'https://www.johnihaas.com/wp-content/uploads/';
const haas = (path) => `${HAAS}${path}`;
const hs = (page) => `https://hopsteiner.us/variety-data-sheets/${page}`;
const faram = (slug) => `https://charlesfaram.com/hop-oracle/${slug}/`;
const yvh = (slug) => `https://yakimavalleyhops.com/products/${slug}`;
const HBC = 'https://www.hopbreeding.com/';
const HPA = (name) => haas(`2024/07/HPA-${name}-Data-Sheet.pdf`);
const NASS25 = 'https://esmis.nal.usda.gov/sites/default/release-files/795696/hopsan25.txt';

